@'
const ts = require('typescript');
const fs = require('node:fs');
const path = require('node:path');
const root = process.cwd();
const config = ts.readConfigFile(path.join(root, 'tsconfig.json'), ts.sys.readFile);
if (config.error) throw new Error(ts.flattenDiagnosticMessageText(config.error.messageText, '\n'));
const parsed = ts.parseJsonConfigFileContent(config.config, ts.sys, root);
const files = [];
function collect(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const filename = path.join(dir, entry.name);
    if (entry.isDirectory()) collect(filename);
    else if (/^audit-v2.*\.(ts|tsx)$/.test(entry.name)) files.push(filename);
  }
}
collect(path.join(root, 'src', '__tests__'));
const program = ts.createProgram([...new Set([...parsed.fileNames, ...files])], { ...parsed.options, noEmit: true, incremental: false });
const diagnostics = ts.getPreEmitDiagnostics(program);
for (const item of diagnostics) {
  const location = item.file && item.start !== undefined ? item.file.getLineAndCharacterOfPosition(item.start) : null;
  console.log((item.file ? path.relative(root, item.file.fileName) : '') + (location ? ':' + (location.line + 1) : '') + ' TS' + item.code + ' ' + ts.flattenDiagnosticMessageText(item.messageText, '\n'));
}
console.log('App plus audit-v2 test/fixture files:', files.length, 'diagnostics:', diagnostics.length);
process.exitCode = diagnostics.length ? 1 : 0;
'@ | node
